mapper.select:


     and member_id = #{memberId}
     and contents like concat('%', #{contents}, '%')
     and pics = #{pics}
     and file_url = #{fileUrl}
     and address = #{address}
     and longitude = #{longitude}
     and latitude = #{latitude}
     and data_id = #{dataId}
     and data_type = #{dataType}
     and like_num = #{likeNum}
     and nolike_num = #{nolikeNum}
     and status = #{status}

     and (status = 1 or (member_id = #{selfPendingMemberId} and status in (0, 2) and del_flag = 0))

        and exists (
            select 1 from ums_member_follow umf
            where umf.member_id = #{followingMemberId}
              and umf.follow_member_id = vcs.member_id
        )


        and not exists (
            select 1 from im_block ib
            where (ib.member_id = #{viewerMemberId} and ib.blocked_member_id = vcs.member_id)
               or (ib.member_id = vcs.member_id and ib.blocked_member_id = #{viewerMemberId})
        )


        and exists (
            select 1 from community_post_member_action bookmark
            where bookmark.post_id = vcs.id
              and bookmark.member_id = #{viewerMemberId}
              and bookmark.action_type = 'BOOKMARK'
        )

     and is_crowdfunding = #{isCrowdfunding}
     and member_nickname like concat('%', #{memberNickname}, '%')
     and member_avatar = #{memberAvatar}
     and member_user_type = #{memberUserType}
     and member_level_id = #{memberLevelId}
     and comment_count = #{commentCount}
     and no_like_count = #{noLikeCount}
     and like_count = #{likeCount}

    and (data_type is null or data_type != 2 or exists (
        select 1 from cms_topic t
        where t.id = vcs.data_id
          and t.del_flag = 0 and t.status = 1 and t.user_status = 1
    ))


order by id desc

select id, route_preview_img as routePreviewImg from ums_creative_square
where id in #{id}
where 1 = 0

select id, member_id as memberId, data_id as dataId, like_type as likeType,
       create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime
from ums_creative_square_like
where member_id = #{memberId}


        and data_id in #{id}

     and 1 = 0

select post_id
from community_post_member_action
where member_id = #{memberId}
  and action_type = 'BOOKMARK'


        and post_id in #{id}

     and 1 = 0

select id, member_id as memberId, follow_member_id as followMemberId,
       create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime
from ums_member_follow
where member_id = #{memberId}


        and follow_member_id in #{id}

     and 1 = 0

select a.id as activityId, a.topic_id as topicId, a.name as sportName, a.img_url as sportCover, t.product_type as productType, t.complete_rule_json as completeRuleJson, t.published_route_graph_json as publishedRouteGraphJson from cms_activity a left join cms_topic t on t.id = a.topic_id
where a.id in #{id}
where 1 = 0

select id as topicId, name as sportName, img_url as sportCover, product_type as productType, complete_rule_json as completeRuleJson, published_route_graph_json as publishedRouteGraphJson, is_template as isTemplate from cms_topic
where id in #{id}
where 1 = 0

mapper.update:
update view_creative_square
member_id = #{memberId}, contents = #{contents}, pics = #{pics}, file_url = #{fileUrl}, address = #{address}, longitude = #{longitude}, latitude = #{latitude}, data_id = #{dataId}, data_type = #{dataType}, like_num = #{likeNum}, nolike_num = #{nolikeNum}, status = #{status}, is_crowdfunding = #{isCrowdfunding}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, member_nickname = #{memberNickname}, member_avatar = #{memberAvatar}, member_user_type = #{memberUserType}, member_level_id = #{memberLevelId}, comment_count = #{commentCount}, no_like_count = #{noLikeCount}, like_count = #{likeCount},
where id = #{id}
